          "species": "Gun Deer - Either Sex (drawn)",
          "season": "Jan 12, 2027–Jan 14, 2027",
          "notes": "Two White-tailed Deer; Either Sex; Limit One Antlerless and One Buck Unlimited Feral Hogs; Either Sex Unlimited Exotic Mammals; Either Sex; Axis, Sika, Aoudad, Mouflon Means: Centerfire Rifles Method: Assigned Blind ; Blinds (pop-up and fixed) are provided by the park. Recommend that you bring your own seating (folding/camp chairs). Please ensure you bring required safety items, including a flashlight and appropriate of hunter safety orange gear. Baiting: Allowed Available: 8; Fee per adult: $ 80.00; Fee per youth: $ 0.00 Application Deadline Expired: September 15, 2026 1 – 4 people per application Baiting allowed; Corn must be labeled for wildlife use (aflatoxin less than 20 ppb) and in it's original container. No other types of baits allowed. Be prepared to walk up to 1/2 mile to assigned blind. Exotics are present but may not appear at every blind. Check-in will be at Park HQ at 9:00 AM. Orientation begins at 11:00 AM at the amphitheater behind the Discovery Center at Guadalupe River State Park. Confirmed hunters need to be at Park no later than 9:15 AM, or they may lose their spot to a standby hunter. Standby hunt spots are not guaranteed. The hunt ends at 30 minutes past sunset on the last hunt day. Hunters are taken to their assigned blind on the first morning of the hunt; hunters are responsible for getting to their assigned blind thereafter. Please call Park at least one week prior to the hunting period if you are planning on staying at the park during the hunting period. Family members who are wishing to camp with hunter will be approved on a case by case basis and will be restricted to the campsite during the hunt period if approved. Standbys may be available. Please call area to confirm.",
